def curriculum(language, level):
    lang = "ar" if language == "ar" else "en"
    level = max(0, min(12, int(level)))
    source = _CURRICULA[lang][level]
    return deepcopy(source)

def all_curricula():
    return {lang: [curriculum(lang, level) for level in range(13)] for lang in ("ar", "en")}

def _step(language, level, index, raw):
    title, target, example, practice, check = raw
    if language == "ar":
        intro = f"تعلم هذا الجزء بالتدرج: {target}."
        repeat = f"1) استمع أو اقرأ المثال. 2) كرره بصوت واضح. 3) طبّق المهارة على عناصر جديدة من هذا المستوى."
    else:
        intro = f"المحتوى الجديد: {target}."
        repeat = f"١) استمع أو اقرأ المثال. ٢) كرره بصوت واضح. ٣) طبّق المهارة على عناصر جديدة من هذا المستوى."
    return {
        "stage": index + 1,
        "title": title,
        "target": target,
        "example": example,
        "instruction": intro,
        "practice": practice,
        "check": check,
        "review": repeat,
    }

def stages(language, level):
    source = curriculum(language, level)
    return [_step(language, level, i, row) for i, row in enumerate(source["steps"])]

def stage(language, level, index):
    items = stages(language, level)
    if 0 <= int(index) < len(items):
        return items[int(index)]
    return {}
